-- Automated 216-Product Seed for PostgreSQL (Kurtis, Bags & Jadau Jewellery with Size-Based Pricing)
ALTER TABLE products ADD COLUMN IF NOT EXISTS sku VARCHAR(40);
ALTER TABLE products ADD COLUMN IF NOT EXISTS sizes JSONB DEFAULT '["Free Size"]'::jsonb;
ALTER TABLE products ADD COLUMN IF NOT EXISTS size_prices_paise JSONB DEFAULT '{}'::jsonb;
